    mat2[15] = quat[0] * quat[5] + quat[1] * quat[7] + quat[2] * quat[4];

    s = quat[0] * mat2[0] + quat[1] * mat2[1] + quat[2] * mat2[2] + quat[3] * mat2[3];

    if (s == 0.0f)
